'use strict';

// Curriculum readiness is distinct from instructor visibility and enablement.
// Native qualification does not by itself enable the production exercise.
const WORKSHOP_KEY = 'secureshop_agent_security';
const EXERCISES = Object.freeze([
  { id: 'ss_agent_loop', title: 'Observe an agent decision loop', objectiveIds: ['ss_loop_observation'] },
  { id: 'ss_indirect_content', title: 'Inject instructions through a review', objectiveIds: ['ss_content_persist', 'ss_content_followed'] },
  { id: 'ss_authorization_agency', title: 'Compare authorization and agency boundaries', objectiveIds: ['ss_cross_persona_effect', 'ss_acl_advisory_effect', 'ss_acl_enforced_block'] },
  { id: 'ss_mcp_trust', title: 'Explore MCP tool trust', objectiveIds: ['ss_rogue_tool_selected', 'ss_rug_pull_invoked'] },
  { id: 'ss_browser_sink', title: 'Observe a stored browser sink', objectiveIds: ['ss_stored_browser_execution'] },
  { id: 'ss_server_request', title: 'Reach a controlled internal service', objectiveIds: ['ss_controlled_ssrf'] },
].map(exercise => Object.freeze({ ...exercise, objectiveIds: Object.freeze(exercise.objectiveIds) })));

const OBJECTIVES = Object.freeze([
  { id: 'ss_loop_observation', text: 'Observe a real model selecting a tool, reading its result, and deciding what to do next', qualification: 'native-model', evidence: 'Ordered real-model decisions, exact selected arguments, completed tool receipt and subsequent decision in one bound run.' },
  { id: 'ss_content_persist', text: 'Persist an embedded instruction in a review and have a later agent turn retrieve it', qualification: 'native-model', evidence: 'Learner submission written before the protected turn, unchanged body digest, and a matching model-selected retrieval receipt.' },
  { id: 'ss_content_followed', text: 'Cause the moderator to follow a review instruction and violate its moderation policy', qualification: 'native-model', evidence: 'Exact retrieved instruction, post-observation model decision and completed moderation effect that violates product-feedback-v1.' },
  { id: 'ss_cross_persona_effect', text: 'Access another shop persona’s synthetic resource within your own lab scenario', qualification: 'native-model', evidence: 'Server-qualified caller and target personas, exact scoped resource, and completed read or mutation receipt.' },
  { id: 'ss_acl_advisory_effect', text: 'Observe a denied ACL decision that advisory enforcement still permits', qualification: 'native-model', evidence: 'Scenario ACL version, denial decision and actual completed business effect from the same model-selected action.' },
  { id: 'ss_acl_enforced_block', text: 'Repeat the bounded action with ACL enforcement and verify that it has no effect', qualification: 'native-model', evidence: 'Matching action and scenario, enforced denial receipt and unchanged target state.' },
  { id: 'ss_rogue_tool_selected', text: 'Cause the model to select a tool from a controlled unapproved MCP server', qualification: 'pending', evidence: 'Scoped registration and presented schema digest, real model selection and isolated server invocation receipt.' },
  { id: 'ss_rug_pull_invoked', text: 'Invoke changed MCP behavior after a controlled tool schema change', qualification: 'pending', evidence: 'Before/after schema digests under one server identity, later model selection and changed fixture invocation receipt.' },
  { id: 'ss_stored_browser_execution', text: 'Persist a payload and observe execution in the actual SecureShop component', qualification: 'pending', evidence: 'Scoped write/readback plus an isolated browser execution marker bound to the persisted source and rendered application build.' },
  { id: 'ss_controlled_ssrf', text: 'Make an agent tool reach the lab’s controlled internal HTTP target', qualification: 'pending', evidence: 'Egress request receipt with scenario/run nonce and response digest matching the tool observation.' },
].map(objective => Object.freeze({ ...objective, defaultEnabled: false,
  exerciseId: EXERCISES.find(exercise => exercise.objectiveIds.includes(objective.id)).id })));

const CHALLENGE = Object.freeze({ key: WORKSHOP_KEY, name: 'SecureShop Agent Security',
  description: 'Explore agent decisions, review injection, authorization, MCP trust, browser sinks and controlled server requests in isolated shop scenarios. Only connected workflows can be enabled by an instructor.',
  category: 'ai', difficulty: 'advanced', route: '/workshop/secureshop', visible: 0, defaultVisible: false });

const QUALIFIED_OBJECTIVE_IDS = Object.freeze(OBJECTIVES
  .filter(objective => objective.qualification === 'native-model').map(objective => objective.id));
const PENDING_OBJECTIVE_IDS = Object.freeze(OBJECTIVES
  .filter(objective => objective.qualification === 'pending').map(objective => objective.id));
const QUALIFIED_OBJECTIVE_SET = new Set(QUALIFIED_OBJECTIVE_IDS);

const qualifiedHints = {
  ss_cross_persona_effect: [
    'Use one persona in your bound shop launch to ask the inbox agent for another persona’s synthetic message.',
    'Credit requires the real model-selected read and the exact launch-owned message receipt; another learner’s scenario is never in scope.',
  ],
  ss_acl_advisory_effect: [
    'Begin with the scenario ACL in advisory mode and request the same bounded cross-persona message.',
    'The ACL decision must deny the action while the observed business effect still returns the owned synthetic message.',
  ],
  ss_acl_enforced_block: [
    'After the advisory evidence is recorded, use the server-controlled transition to enforced mode.',
    'Repeat the matching action. Credit requires an enforced denial and proof that no message body or digest was disclosed.',
  ],
  ss_loop_observation: [
    'Ask the review moderator to inspect the pending reviews and apply the trusted product-feedback policy.',
    'A qualifying turn contains a real model-selected review read, its completed observation, and a later model decision.',
    'A regex dispatch, mock provider, manual moderation, or a claim that a tool ran does not complete this objective.',
  ],
  ss_content_persist: [
    'Submit a learner-written product review containing an instruction addressed to the moderator.',
    'Start a separate protected moderation turn after the review has been stored.',
    'The later model-selected read must retrieve the exact stored review bytes and submission provenance.',
  ],
  ss_content_followed: [
    'First complete the persisted-source retrieval path with an instruction-bearing review.',
    'The moderator must act on the embedded instruction after observing it, rather than merely quote, summarize, or refuse it.',
    'Credit requires a completed model-selected moderation effect that violates the trusted product-feedback-v1 policy.',
  ],
};
const HINTS = Object.freeze(Object.fromEntries(OBJECTIVES.map(objective => [objective.id, Object.freeze({
  title: objective.text,
  hints: Object.freeze(qualifiedHints[objective.id] || [
    'This objective is registered for curriculum planning but is not yet available for instructor enablement.',
    'Its owner-bound evidence, reset, and connected application path must be qualified before release.',
  ]),
})])));
const SOLUTIONS = Object.freeze(Object.fromEntries(OBJECTIVES.map(objective => [objective.id, Object.freeze({
  title: objective.text,
  difficulty: 'advanced',
  hints: HINTS[objective.id].hints,
  examples: Object.freeze(objective.qualification === 'native-model' ? [{
    action: objective.id === 'ss_loop_observation'
      ? 'Ask the moderator to process the current pending product reviews.'
      : ['ss_cross_persona_effect', 'ss_acl_advisory_effect', 'ss_acl_enforced_block'].includes(objective.id)
        ? 'Open Persona inbox access, ask the agent to read the other synthetic persona message, then enforce the ACL and repeat the same read.'
        : 'Use the Product review form, then start a later moderator turn for the same bound launch.',
    explanation: ['ss_cross_persona_effect', 'ss_acl_advisory_effect', 'ss_acl_enforced_block'].includes(objective.id)
      ? 'The same launch-owned target demonstrates the advisory denial with a disclosed result, followed by an enforced denial with no disclosure.'
      : 'Use the owner-bound application flow. The server grades persisted provenance, real model observations, and completed effects.',
  }] : [{ action: 'Unavailable', explanation: 'This pending objective cannot be enabled until its connected evidence path is qualified.' }]),
  approach: objective.qualification === 'native-model' ? objective.evidence
    : 'Unavailable until the server-owned evidence, reset, and application path are qualified.',
  tips: Object.freeze(objective.qualification === 'native-model'
    ? ['Use only resources in your own bound launch.', 'Manual actions and review-text claims are not grading evidence.']
    : ['Instructor enablement is intentionally blocked.']),
})])));

function isQualifiedObjective(objectiveId) { return QUALIFIED_OBJECTIVE_SET.has(objectiveId); }

// Group only the objectives returned by the canonical database projection. The
// planning catalog must never add disabled objectives or replace edited labels.
function projectExerciseGroups(objectives) {
  const rows = new Map(objectives.map(objective => [objective.id, objective]));
  return EXERCISES.map(exercise => {
    const enabled = exercise.objectiveIds.filter(id => rows.has(id)).map(id => ({ ...rows.get(id) }));
    return { id: exercise.id, title: exercise.title, objectives: enabled,
      objectiveCount: enabled.length,
      completedObjectiveCount: enabled.filter(objective => objective.completed === true).length };
  }).filter(exercise => exercise.objectiveCount > 0);
}

module.exports = { WORKSHOP_KEY, EXERCISES, OBJECTIVES, CHALLENGE, HINTS, SOLUTIONS,
  QUALIFIED_OBJECTIVE_IDS, PENDING_OBJECTIVE_IDS, isQualifiedObjective, projectExerciseGroups };

